class Reassembler:
    def __init__(self):
        self._buf = bytearray()

    def feed(self, chunk: bytes) -> list[bytes]:
        frames = []
        try:
            if chunk:
                self._buf.extend(chunk)
        except Exception:
            pass

        buf = self._buf
        pos = 0

        while pos < len(buf):
            idx = buf.find(b'\xAA\x55', pos)
            if idx == -1:
                if buf[-1] == 0xAA:
                    pos = len(buf) - 1
                else:
                    pos = len(buf)
                break

            pos = idx
            if len(buf) - pos < 4:
                break

            length = buf[pos + 2] | (buf[pos + 3] << 8)
            if length > 4096:
                pos += 2
                continue

            frame_len = 4 + length + 1
            if len(buf) - pos < frame_len:
                break

            payload = bytes(buf[pos + 4:pos + 4 + length])
            check = buf[pos + 4 + length]

            xor = 0
            for b in payload:
                xor ^= b

            if xor == check:
                frames.append(payload)

            pos += frame_len

        if pos:
            del buf[:pos]

        return frames
